"""Pinned James bfcbbf24 outputs, generated by compare_sources.py, not the port."""
import math

import pytest

from openpilot.sunnypilot.selfdrive.controls.lib.honda_eps import core


def test_canonical_outputs_match_pinned_james_trace():
  expected = {
    0: .016693832474577824,
    50: .3227565918605221,
    100: .17636980756334725,
    500: -.19958028478364773,
    799: -.031058524884660575,
    825: .008957349512730035,
    900: .1163748086388168,
    999: .10983836427692488,
    1400: .866351484160702,
    1999: .03982932607505957,
  }
  ff = core.HondaEpsFirmwareFeedforward(.01, cal=core.INSIGHT_TXM_A040_CANONICAL, load=core.INSIGHT_TXM_EPS_LOAD)
  controller = core.HondaEpsLateralCore((0., 11.175, 11.176, 22.352), (.018, .024, .048, .060),
                                     (0., 11.175, 11.176, 22.352), (.006, .008, .016, .020), .01,
                                     ff=ff, p_scale=core.INSIGHT_P_SCALE, i_scale=core.INSIGHT_I_SCALE)
  for frame in range(2000):
    time = frame * .01
    desired = 30. * math.sin(time * .6) + 1.5 * math.sin(time * 5.)
    measured = 30. * math.sin((time - .08) * .6)
    if 13 <= time < 14:
      measured -= 80.
    pressed = 8 <= time < 8.5
    limited = pressed or 8.5 <= time < 10.
    output = controller.update(desired, .2, measured, 12., .025 * math.sin(time * .2), pressed, limited)
    if frame in expected:
      assert output == pytest.approx(expected[frame], abs=1e-12)
      assert -4096. * (output * (3840. / 4096.)) == pytest.approx(-3840. * expected[frame], abs=1e-8)
